	if !m.showHelp {
		t.Error("? 应打开帮助")
	}
	v := m.View()
	for _, want := range []string{"键位帮助", "切换分类", "Enter", "浏览器打开"} {
		if !strings.Contains(v, want) {
			t.Errorf("帮助视图缺少 %q", want)
		}
	}
	m = asModel(m.handleListKey(tea.KeyMsg{Type: tea.KeyRunes, Runes: []rune{'?'}}))
	if m.showHelp {
		t.Error("再次 ? 应关闭帮助")
	}
}

