// matchFilter 检查 text 是否匹配 filter，支持简繁中文双向匹配。
func matchFilter(text, filter string) bool {
    // 第一轮：原始匹配（不区分大小写）
    if strings.Contains(strings.ToLower(text), strings.ToLower(filter)) {
        return true
    }
    // 第二轮：简繁一致性 — 双方统一转简体后再匹配
    textNorm := s2t.Normalize(text)      // 繁→简
